"""vad_action — 把「调整静音判定」包装成一个意图动作（语音现场校准）

流程:
  语音命中语音校准 → 日志提示「随便说一句话」→ 从【已有麦克风读取线程】tee 采集
  vad_calib_seconds 秒（不额外开设备）→ 现场分析【这句的句内停顿】→ 定停止窗
  → 应用到运行中的 VAD + 落档案（同一段音频顺带校准 预滚 与 ASR 前增益）

单句判据（2026-10-19 用户口径：说一句就够）:
  句内最大停顿 max_int → 停止窗 = clamp(1.35×max_int, 512ms, 864ms)
  （比句内最长停顿宽 → 不会被逗号切开；不高于 864ms → 不会把两句粘成一段）
  这一句里没测到停顿（没逗号/没停）→ 保持原值，不缩短，并提示下次中间停一下
"""
from __future__ import annotations

import threading
import time

_HERE = None
_AGENT = None
_tap = {"active": False, "buf": [], "deadline": 0.0, "running": False}

PROMPT_DEFAULT = ("我现在说一句话，测试一下静音判定，看看能不能校准得准。")   # 单句（带逗号停顿）


def set_agent(agent):
    global _AGENT
    _AGENT = agent


def _log(msg, tag="MIC", level=None):
    try:
        from dlog import log
        log(msg, tag, level=level)
    except Exception:
        print(msg, flush=True)


# ---- 读取线程 tee（必须非阻塞） ----
def feed(block):
    if not _tap["active"]:
        return
    try:
        import numpy as np
        _tap["buf"].append(np.asarray(block, dtype=np.float32).ravel().copy())
    except Exception:
        return
    if _tap["deadline"] and time.time() >= _tap["deadline"] and not _tap["running"]:
        _tap["running"] = True
        threading.Thread(target=_finish, daemon=True, name="oc-vadcalib").start()


# ---- 意图动作（dispatch 签名: (arg, cfg, dry=False) -> (ok, msg, info)） ----
def act_vad_calibrate(arg, cfg, dry=False):
    b = getattr(cfg, "behavior", {}) or {}
    prompt = b.get("vad_calib_prompt") or PROMPT_DEFAULT
    test_s = float(b.get("vad_calib_seconds", 8) or 8)
    # ★ 只需【一句话】（用户口径）：按这句的句内停顿自动定停止窗 —— 不用再"读两遍+中间停"
    _log("🎯 语音校准：随便说一句话就行（3–6 秒，中间带个逗号/停一下）", level="info")
    _log(f"   例：「{prompt}」", level="info")
    _log("   （说完不用按键；结果自动打出来：新的停止窗 + 预滚 + ASR 增益）", level="info")
    if dry:
        return True, "[dry] 语音校准（不采集）", {}
    _tap.update(active=True, buf=[], deadline=time.time() + test_s, running=False)
    return True, f"语音校准已开始（采集 {test_s:.0f}s，请按上面提示说一句）", {"prompt": prompt}


def _finish():
    global _AGENT
    try:
        import numpy as np
        from .vad_calib import analyze_arrays
        from .vad_adapt import save as _save, speaker as _speaker

        arrays = [a for a in _tap["buf"] if getattr(a, "size", 0)]
        _tap.update(active=False, buf=[])
        if not arrays:
            _log("   ⚠️ 没有采到音频，校准取消")
            return
        x = np.concatenate(arrays)
        _res = analyze_arrays([x], min_speech_frames=3)
        pauses, n = _res["pauses"], _res["n_files"]
        # ⚠️ 血债（讲解子代理交叉检查抓到）：这里原来引用 `b`/`old`/`target` —— 都是
        #   act_vad_calibrate 里的局部名，在 _finish 里【未定义】→ 单句校准必然
        #   NameError（"说一句话校准"这条链路是死的）。现在全部就地取/先算。
        _b = getattr(getattr(_AGENT, "cfg", None), "behavior", {}) or {}
        sm = getattr(getattr(_AGENT, "seg", None), "sm", None)
        old = int(getattr(sm, "required_misses", 0)) * 32 if sm is not None else None
        # ★ 单句校准（用户口径：说一句话就够）：停止窗 = clamp(1.35×句内最大停顿, 下限, 864ms)
        #   为什么 1.35×：停止窗要比"句内最长停顿"宽一点，才不会被逗号把句子切开；
        #   下限 500ms = 用户指定；上限 864ms = 别把两句话粘成一个段。
        _min_ms = float(_b.get("vad_calib_min_ms", 500) or 500)
        _fac = float(_b.get("vad_calib_factor", 1.35) or 1.35)
        _max_ms = 864.0
        if not pauses:
            misses = max(int(round(_min_ms / 32.0)),
                         int(round(float(old or _min_ms) / 32.0)))
            _log(f"   ⚠️ 这句话里没测到句内停顿（没有逗号/停顿）→ 停止窗保持不缩短"
                 f"（{misses*32}ms）；下次说的时候中间停一下", level="info")
        else:
            _max_int = max(pauses)
            target_ms = max(_min_ms, min(_max_ms, _fac * _max_int))
            misses = int(round(target_ms / 32.0))
            _log(f"   本句句内最大停顿 {_max_int:.0f}ms → 停止窗 {target_ms:.0f}ms"
                 f"（×{_fac:.2f}，下限 {_min_ms:.0f}/上限 {_max_ms:.0f}）", level="info")
        misses = max(int(round(_min_ms / 32.0)), min(30, misses))

        # 同时写两个后端的停止窗 + 内存配置（见 AdaptiveVad.set_window_ms）
        try:
            from .vad_adapt import AdaptiveVad
            ad = AdaptiveVad(_AGENT)
            ad.set_window_ms(misses * 32, "语音校准")
            # ★ 预滚/句首余量：同一段测试音频现场算（段首静音 + 段首能量比）
            try:
                from .vad_calib import analyze_arrays as _aa, recommend_preroll as _rp
                res = _aa([x], min_speech_frames=3)
                if res["n_files"]:
                    pre = _rp(res)
                    ad.set_preroll(pre, "语音校准")
            except Exception as _e5:
                _log(f"   ⚠️ 预滚现场校准跳过: {type(_e5).__name__}: {_e5}")
            # ★ ASR 前增益上限：按本次真实峰值算（到 0.6 需要多少倍），并做一次非空复核
            try:
                _b = getattr(getattr(_AGENT, "cfg", None), "behavior", {}) or {}
                _pk = float(np.abs(x).max())
                _cur = int(_b.get("asr_gain_cap", 200))
                if _pk > 1e-6:
                    _need = 0.6 / _pk
                    _want = int(min(600, max(_cur, np.ceil(_need * 1.2))))
                    _y = np.clip(x * min(0.6 / _pk, _want), -1, 1)
                    _t2 = ""
                    try:
                        if getattr(_AGENT, "asr", None) is not None:
                            _t2 = (_AGENT.asr.transcribe(_y) or "").strip()
                    except Exception:
                        _t2 = ""
                    if not _t2:
                        # ⚠️ 血债（2026-10-19）：原来"复核空文本就再翻倍" → 一段噪声/静音
                        #   也能把上限从 200 抬到 400/600 一直顶到 600（600× 会把音频推爆）。
                        #   现在：只有【峰值确实很低（<0.02）】才允许翻倍，且总上限 300。
                        if _pk < 0.02:
                            _want = int(min(300, _want * 2))
                    _b["asr_gain_cap"] = _want
                    _save(misses, "voice-calib", _speaker(),
                          extra={"asr_gain_cap": _want, "peak": round(_pk, 5),
                                 "need_gain": round(_need, 1)})
                    _log(f"   ASR 前增益上限已校准：{_cur}→{_want}×"
                         f"（本次峰值 {_pk:.4f} → 需 {_need:.0f}×；复核"
                         f"{'有文本' if _t2 else '仍空→再翻倍'}）", level="info")
            except Exception as _e6:
                _log(f"   ⚠️ ASR 增益校准跳过: {type(_e6).__name__}: {_e6}")
        except Exception:
            if sm is not None:
                sm.required_misses = misses
        _max_int = max(pauses) if pauses else 0
        _save(misses, "voice-calib", _speaker(),
              extra={"max_internal_ms": _max_int, "window_ms": misses * 32,
                     "n_pauses": len(pauses), "one_sentence": True})
        _log(f"✅ 语音校准完成：停止窗 {old}→{misses*32}ms（silero misses={misses}）"
             f"｜本句句内最大停顿 {_max_int:.0f}ms（共 {len(x)/16000:.1f}s 音频，"
             f"{len(pauses)} 个停顿）", level="info")
    except Exception as e:
        _log(f"   ⚠️ 静音判定校准失败: {type(e).__name__}: {e}")
    finally:
        _tap["running"] = False
